import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// ==================== 技能 ====================
// 分类/类型/行动类型：已知值为推荐项，允许新值扩展（union+string兜底）
const 技能Schema = z.object({
  分类: z.union([z.enum(['基础', '高级', '银色']), z.string()]).prefault('基础'),
  类型: z.union([z.enum(['主动', '被动', '光环', '辅助', '制造系']), z.string()]).prefault('主动'),
  行动类型: z.union([z.enum(['主要行动', '次要行动', '反应动作', '免费行动', '无']), z.string()]).prefault('主要行动'),
  关联属性: z.string().prefault(''),
  消耗: z.string().prefault(''),
  冷却: z.string().prefault(''),
  射程: z.string().prefault(''),
  目标: z.string().prefault(''),
  阶位: z.string().prefault(''),
  属性要求: z.string().prefault(''),
  等级: z.coerce.number().prefault(1),
  效果: z.record(
    z.string().describe('特效名'),
    z.any().describe('文字说明或结构化效果数据')
  ).prefault({}),
}).catchall(z.any()).prefault({});

// ==================== 装备 ====================
const 装备槽Schema = z.object({
  名称: z.string().prefault('无'),
  类型: z.string().prefault('无'),
  品质: z.string().prefault('无'),
  阶位: z.string().prefault('无'),
  穿戴门槛: z.string().prefault('无'),
  强化等级: z.coerce.number().prefault(0),
  伤害骰: z.string().prefault('无'),
  倍率: z.coerce.number().prefault(0),
  主属性: z.string().prefault('无'),
  副属性: z.string().prefault('无'),
  主属性加成: z.coerce.number().prefault(0),
  副属性加成: z.coerce.number().prefault(0),
  装备防御: z.coerce.number().prefault(0),
  装备闪避: z.coerce.number().prefault(0),
  负重: z.coerce.number().prefault(0),
  效果: z.union([
    z.record(z.string().describe('效果编号/名称'), z.string().describe('具体效果描述')),
    z.string()
  ]).transform(v => typeof v === 'string' ? {} : v).prefault({}),
  描述: z.string().prefault('无'),
  数量: z.coerce.number().prefault(1),
}).prefault({});

const 装备Schema = z.object({
  头部: 装备槽Schema,
  躯干: 装备槽Schema,
  手部: 装备槽Schema,
  下装: 装备槽Schema,
  饰品: 装备槽Schema,
  主武器: 装备槽Schema,
  副武器: 装备槽Schema,
}).prefault({});

// ==================== 属性 ====================
const 属性基础Schema = z.object({
  STR: z.coerce.number().prefault(5),
  AGI: z.coerce.number().prefault(5),
  CON: z.coerce.number().prefault(5),
  PER: z.coerce.number().prefault(5),
}).prefault({});

const 属性加成Schema = z.object({
  STR: z.coerce.number().prefault(0),
  AGI: z.coerce.number().prefault(0),
  CON: z.coerce.number().prefault(0),
  PER: z.coerce.number().prefault(0),
}).prefault({});

// 属性块：实际=基础+加成+自定义加成（transform自动计算，二次parse幂等）
// 属性修正值为纯存储字段，由前端脚本计算写入，AI严禁手动更新
const 属性块Schema = z.object({
  基础: 属性基础Schema,
  加成: 属性加成Schema,
  自定义加成: 属性加成Schema,
  实际: 属性基础Schema,
  属性修正值: z.object({
    STR: z.coerce.number().prefault(0),
    AGI: z.coerce.number().prefault(0),
    CON: z.coerce.number().prefault(0),
    PER: z.coerce.number().prefault(0),
  }).describe('前端脚本计算写入，AI严禁手动更新').prefault({}),
  未分配属性点: z.coerce.number().prefault(0),
}).prefault({}).transform(data => ({
  ...data,
  实际: {
    STR: data.基础.STR + data.加成.STR + data.自定义加成.STR,
    AGI: data.基础.AGI + data.加成.AGI + data.自定义加成.AGI,
    CON: data.基础.CON + data.加成.CON + data.自定义加成.CON,
    PER: data.基础.PER + data.加成.PER + data.自定义加成.PER,
  },
}));

// ==================== 衍生属性 / 状态 / 背包 ====================
const 衍生属性Schema = z.object({
  HP_当前: z.coerce.number().prefault(0),
  HP_最大: z.coerce.number().prefault(0),
  HP额外加成: z.coerce.number().prefault(0),
  MP_当前: z.coerce.number().prefault(0),
  MP_最大: z.coerce.number().prefault(0),
  MP额外加成: z.coerce.number().prefault(0),
  耐力_当前: z.coerce.number().prefault(0),
  耐力_最大: z.coerce.number().prefault(0),
  耐力额外加成: z.coerce.number().prefault(0),
  防御: z.coerce.number().prefault(0),
  防御额外加成: z.coerce.number().prefault(0),
  闪避值: z.coerce.number().prefault(0),
  闪避额外加成: z.coerce.number().prefault(0),
  移动距离: z.coerce.number().prefault(0),
  移动距离额外加成: z.coerce.number().prefault(0),
  负重_当前: z.coerce.number().prefault(0),
  负重_上限: z.coerce.number().prefault(0),
  负重额外加成: z.coerce.number().prefault(0),
}).prefault({});

const 特殊状态条目Schema = z.union([
  z.string().describe('兼容旧格式：直接写状态说明'),
  z.object({
    分类: z.string().prefault('其他').describe('增益、减益或其他状态'),
    说明: z.string().prefault(''),
    来源: z.string().prefault(''),
    持续时间: z.string().prefault(''),
    层数: z.coerce.number().optional(),
  }).catchall(z.any()),
]);

const 状态Schema = z.object({
  生命状态: z.union([z.enum(['健康', '受伤', '重伤', '濒死']), z.string()]).prefault('健康'),
  // 增益与减益继续归入特殊状态；旧文本格式保留兼容
  特殊状态: z.record(z.string().describe('状态名'), 特殊状态条目Schema).prefault({}),
}).prefault({});

const 背包Schema = z.record(
  z.string().describe('物品名。注意分类判断：1.装备(分为武器、防具、饰品)，需包含[品质]、[类型]、[伤害骰/防御/加成]等完整装备字段；2.普通物品(分为消耗品和特殊道具)，只需具备[数量]和[描述]字段即可；3.其他契约者的持有UP以条目形式记录（如：现金UP，数量为其UP数额）'),
  z.object({
    描述: z.string().prefault(''),
    数量: z.coerce.number().prefault(0),
  }).catchall(z.any()).prefault({}),
).prefault({}).transform(data => _.pickBy(data, ({ 数量 }) => 数量 > 0));

// ==================== 头部组件（天赋/血统/称号） ====================
const 天赋Schema = z.object({
  名称: z.string().prefault('无'),
  品质: z.string().prefault('无'),
  属性加成: z.string().prefault('无'),
  效果: z.record(
    z.string().describe('特效名'),
    z.string().describe('特效描述')
  ).prefault({}),
}).prefault({});

const 血统Schema = z.object({
  名称: z.string().prefault('无'),
  品质: z.string().prefault('无'),
  属性加成: z.string().prefault('无'),
  效果: z.record(
    z.string().describe('特效名'),
    z.string().describe('特效描述')
  ).prefault({}),
}).prefault({});

const 称号Schema = z.object({
  名称: z.string().prefault('无'),
  效果: z.record(
    z.string().describe('特效名'),
    z.string().describe('特效描述')
  ).prefault({}),
}).prefault({});

// ==================== 转职树（固定四层，工厂函数组装） ====================
const 转职详情Schema = z.object({
  详细内容: z.string().prefault('无'),
  效果: z.string().prefault('无'),
  主属性加成: z.object({
    属性: z.string().prefault('无'),
    值: z.coerce.number().prefault(0),
  }).prefault({}),
  副属性加成: z.object({
    属性: z.string().prefault('无'),
    值: z.coerce.number().prefault(0),
  }).prefault({}),
  // 职业特性兼容普通特性叶节点，也支持任意层级的命名分组，供前端递归折叠显示
  职业特性: z.record(
    z.string().describe('特性名或分组名'),
    z.union([z.string(), z.record(z.string(), z.any())]).prefault({}),
  ).prefault({}),
  职业技能: z.record(z.string().describe('技能名'), 技能Schema).prefault({}),
}).prefault({});

const 转职节点状态Schema = z.union([z.enum(['未解锁', '未选择', '当前', '已完成', '跳过', '已放弃']), z.string()]).prefault('未选择');

// 最深层：隐藏转职节点（无下一层，分支仅作形态命名记录）
const 隐藏转职节点Schema = z.object({
  状态: 转职节点状态Schema,
  详情: 转职详情Schema,
  分支: z.record(z.string().describe('隐藏转职后的形态或命名'), z.any()).prefault({}),
}).prefault({});

// 转职层工厂函数：传入下一层Schema，返回当前层Schema
const 转职层Schema = (下一层Schema) => z.object({
  状态: 转职节点状态Schema,
  详情: 转职详情Schema,
  分支: z.record(
    z.string().describe('转职方向名，每个节点至少衍生2个分支'),
    下一层Schema
  ).prefault({}),
}).prefault({});

// 固定四层组装：一转 -> 二转 -> 三转 -> 隐藏转职
const 三转节点Schema = 转职层Schema(隐藏转职节点Schema);
const 二转节点Schema = 转职层Schema(三转节点Schema);
const 一转节点Schema = 转职层Schema(二转节点Schema);

// ==================== 通用特殊资源 ====================
// 新资源统一放在“契约者.特殊资源”或对应实体的“特殊资源”下，按来源分组
// 例：特殊资源.职业.魔能祈唤.魔能爆裂 = {当前: 2, 上限: 2, 说明: "...", 恢复方式: "短休"}
// 资源名和自定义字段不设固定清单，以支持新职业、新装备和新规则
const 特殊资源Schema = z.record(
  z.string().describe('来源/类别分组名，如职业、装备、血统、天赋、技能、其他'),
  z.any().describe('资源条目或子分组；消耗型条目建议记录当前、上限、说明、来源、恢复方式，并可扩展自定义字段')
).prefault({}).describe('通用特殊资源池。新资源写入此字段，不新增固定职业资源字段；允许自定义分组、嵌套及条目字段。');

// ==================== 职业 ====================
const 职业Schema = z.object({
  名称: z.string().prefault('无'),
  稀有度: z.string().prefault('无'),
  转职阶段: z.string().prefault('无'),
  职业等级: z.coerce.number().prefault(0),
  PEXP_当前: z.coerce.number().prefault(0),
  PEXP_升级所需: z.coerce.number().prefault(0),
  主属性加成: z.object({
    属性: z.string().prefault('无'),
    值: z.coerce.number().prefault(0),
  }).prefault({}),
  副属性加成: z.object({
    属性: z.string().prefault('无'),
    值: z.coerce.number().prefault(0),
  }).prefault({}),
  职业简介: z.string().prefault('无').describe('职业的简短介绍、机制方向与发展定位'),
  职业技能: z.record(z.string().describe('技能名'), 技能Schema).prefault({}),
  // 职业特性兼容普通特性叶节点，也支持任意层级的命名分组，供前端递归折叠显示
  职业特性: z.record(
    z.string().describe('特性名或分组名'),
    z.union([z.string(), z.record(z.string(), z.any())]).prefault({}),
  ).prefault({}),
  传承技能: z.record(z.string().describe('技能名'), 技能Schema).prefault({}),
  转职树: z.object({
    名称: z.string().prefault('无'),
    状态: z.union([z.enum(['当前', '已完成']), z.string()]).prefault('当前'),
    分支: z.record(
      z.string().describe('一转方向名，每个节点至少衍生2个分支'),
      一转节点Schema
    ).prefault({}),
  }).prefault({}),
}).catchall(z.any()).prefault({});

// ==================== 实体Schema（统一超集：小队成员 / 其他契约者 / 副本角色） ====================
const 实体Schema = z.object({
  外貌: z.string().prefault(''),
  类型: z.union([
    z.enum([
      '小队成员',
      '其他契约者',
      '杂兵', '精英', 'BOSS', '隐藏BOSS',
      '精英（固有角色）', 'BOSS（固有角色）', '隐藏BOSS（固有角色）'
    ]),
    z.string()
  ]).describe('实体类别，与存储位置对应：小队.成员下填小队成员；其他契约者下填其他契约者；副本角色下填杂兵/精英/BOSS/隐藏BOSS或固有角色').prefault('杂兵'),
  构筑: z.string().describe('敌人按16种属性基底写明战术流派；契约者写小队定位与配置思路；小队成员填无').prefault('无'),
  好感度: z.coerce.number().transform(v => _.clamp(v, -100, 100)).prefault(0),
  头部: z.object({
    等级: z.coerce.number().prefault(1),
    EXP_当前: z.coerce.number().prefault(0),
    EXP_升级所需: z.coerce.number().prefault(50),
    阶位: z.string().prefault('一阶'),
    属性软上限: z.coerce.number().prefault(25),
    军衔: z.string().prefault('列兵'),
    RP_当前: z.coerce.number().prefault(0),
    RP_下一级: z.coerce.number().prefault(15),
    天赋: 天赋Schema,
    血统: 血统Schema,
    称号: z.object({
      当前称号: 称号Schema,
      '备用称号（只记录不生效）': 称号Schema,
    }).prefault({}),
  }).prefault({}),
  属性: 属性块Schema,
  衍生属性: 衍生属性Schema,
  职业: 职业Schema,
  // 特殊资源可记录该实体由装备、血统、天赋、技能或职业提供的额外资源池
  特殊资源: 特殊资源Schema,
  通用技能: z.record(z.string().describe('技能名'), 技能Schema).prefault({}),
  装备: 装备Schema,
  状态: 状态Schema,
  背包: 背包Schema,
}).prefault({});

// ==================== 主Schema ====================
export const Schema = z.object({
  系统日志: z.array(z.string()).prefault([]),

  契约者: z.object({
    当前世界: z.enum(['现实', '回廊', '副本']).prefault('现实'),
    当前时间: z.object({
      现实日期: z.string().prefault('2025年5月10日'),
      现实时间: z.string().prefault('凌晨00:01'),
      副本日期: z.string().prefault('不在副本中'),
      副本时间: z.string().prefault('不在副本中'),
      客观时间: z.string().prefault('不在副本中'),
      地点: z.string().prefault('未知区域'),
      阶段进度: z.string().prefault('0%'),
    }).prefault({}),

    头部: z.object({
      姓名: z.string().prefault(''),
      等级: z.coerce.number().prefault(1),
      EXP_当前: z.coerce.number().prefault(0),
      EXP_升级所需: z.coerce.number().prefault(50),
      阶位: z.string().prefault('一阶'),
      属性软上限: z.coerce.number().prefault(25),
      军衔: z.string().prefault('列兵'),
      RP_当前: z.coerce.number().prefault(0),
      RP_下一级: z.coerce.number().prefault(15),
      天赋: 天赋Schema,
      血统: z.object({
        名称: z.string().prefault('普通地球人类'),
        品质: z.string().prefault('白色'),
        属性加成: z.string().prefault('无'),
        效果: z.record(
          z.string().describe('特效名'),
          z.string().describe('特效描述')
        ).prefault({}),
      }).prefault({}),
      称号: z.object({
        当前称号: 称号Schema,
        '备用称号（只记录不生效）': 称号Schema,
      }).prefault({}),
      CR: z.coerce.number().transform(v => _.clamp(v, 1, 10)).prefault(3),
      回廊态度: z.string().prefault('观察'),
    }).prefault({}),

    属性: 属性块Schema,

    衍生属性: 衍生属性Schema,
    职业: 职业Schema,
    // 通用特殊资源池；资源来源不限于职业，装备、血统、天赋、技能等均可分组记录
    特殊资源: 特殊资源Schema,
    通用技能: z.record(z.string().describe('技能名'), 技能Schema).prefault({}),
    装备: 装备Schema,

    经济: z.object({
      UP: z.coerce.number().prefault(0),
    }).prefault({}),

    个人产业: z.object({
      当前店铺: z.object({
        名称: z.string().prefault('无'),
        等级: z.string().prefault('无'),
        所属行业: z.string().prefault('无'),
        租金到期日: z.string().prefault('无'),
        设施清单: z.record(z.string(), z.string()).prefault({}),
        雇员状态: z.string().prefault('无'),
      }).prefault({}),
      代工与订单: z.object({
        进行中订单: z.record(z.string(), z.any()).prefault({}),
        冻结资金_UP: z.coerce.number().prefault(0),
      }).prefault({}),
    }).prefault({}),

    状态: 状态Schema,
    背包: 背包Schema,

    副本经历: z.record(
      z.string().describe('副本名'),
      z.object({
        评价等级: z.string().prefault(''),
        简要说明: z.string().prefault(''),
      }).prefault({}),
    ).prefault({}),

    人际关系: z.record(
      z.string().describe('角色名（副本NPC与其他契约者，小队成员的好感度在实体内管理）'),
      z.object({
        关系: z.string().prefault(''),
        好感度: z.coerce.number().prefault(0),
      }).prefault({}),
    ).prefault({}),

    小队: z.object({
      名称: z.string().prefault('无'),
      成员: z.record(
        z.string().describe('成员名。契约角色，永久成员，类型字段填小队成员，好感度在实体内管理'),
        实体Schema
      ).prefault({}),
    }).prefault({}),

    其他契约者: z.record(
      z.string().describe('契约者姓名。类型字段填其他契约者，击杀掉落血腥钥匙，持有UP以条目形式记录在背包中。副本结算时清空'),
      实体Schema
    ).prefault({}),

    副本角色: z.record(
      z.string().describe('角色名。类型字段填杂兵/精英/BOSS/隐藏BOSS（主线敌人）或固有角色。敌我关系统一由正文叙事体现。副本结算时清空'),
      实体Schema
    ).prefault({}),

    其他契约者名单: z.record(
      z.string().describe('契约者姓名（副本生成时的资料数据）'),
      z.object({
        称号: z.string().prefault('无'),
        等级: z.coerce.number().prefault(1),
        阵营: z.string().prefault('未知'),
        状态: z.string().prefault('存活'),
      }).prefault({}),
    ).prefault({}),

    固有角色名单: z.record(
      z.string().describe('固有角色名（副本生成时的资料数据，与"副本角色"实体分开，此为轻量索引，遭遇建立完整实体后仍保留此条目作总览）'),
      z.object({
        位阶: z.string().prefault('一阶'),
        等级: z.coerce.number().prefault(1),
        状态: z.string().prefault('存活'),
      }).prefault({}),
    ).prefault({}),

    当前副本元数据: z.object({
      副本名称: z.string().prefault('未生成'),
      副本来源: z.string().prefault('未生成'),
      副本类型: z.union([z.enum(['和平', '阵营', '血腥', '未生成']), z.string()]).prefault('未生成'),
      时间限制: z.string().prefault('未生成'),
      基准等级: z.coerce.number().prefault(1),
    }).prefault({}),

    当前副本任务: z.object({
      主线任务: z.object({
